/// Runtime route applier implemented by app-level composition code.
pub trait AppRuntimeRouteApplier {
    /// Проверяет все owner boundaries до первой мутации.
    fn preflight_committed_routes(
        &mut self,
        routes: &[RuntimeCommittedRoute],
    ) -> SettingsResult<Option<AppRouteApplyReport>>;

    /// Applies one typed committed route and returns a detailed route report.
    fn apply_committed_route(
        &mut self,
        route: RuntimeCommittedRoute,
    ) -> SettingsResult<AppRouteApplyReport>;

    /// Восстанавливает один ранее committed route в compensating transaction.
    fn rollback_committed_route(
        &mut self,
        route: RuntimeCommittedRoute,
    ) -> SettingsResult<AppRouteApplyReport>;

    /// Завершает irreversible work после успешной atomic persistence.
    fn finalize_committed_routes(&mut self);
}

/// Project-specific route result without deferred outcomes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AppRouteApplyResult {
    /// Route fully applied the update.
    Applied,

    /// Route was already in the requested state.
    Noop,

    /// Previously active preview became committed state.
    PreviewPromoted,

    /// Значение принято и будет сохранено, но живой runtime намеренно не менялся:
    /// эффект наступит после перезапуска приложения. Отличается от `Noop` («уже в нужном
    /// состоянии») и от `Applied` («runtime изменён»).
    AppliesAfterRestart,

    /// Only part of the route applied.
    PartialFailure { message: String },

    /// Route failed before applying the requested update.
    Failed { message: String },

    /// Renderer recreation failed; apply/rollback causes остаются typed и раздельными.
    RendererRecreationFailed {
        /// Полная typed failure без string flattening owner boundary.
        failure: RendererRecreationFailure,
    },

    /// Runtime owner boundary временно занята; update не применён и не поставлен в очередь.
    RuntimeBusy {
        /// Активная non-interruptible operation.
        activity: SettingsBoundaryActivity,
    },

    /// Route generation conflict blocked apply.
    Conflict {
        /// Generation captured by the editing transaction.
        baseline: RouteGeneration,

        /// Current generation seen before apply.
        current: RouteGeneration,
    },
}

impl AppRouteApplyResult {
    /// Returns true only for states that mean runtime reached the requested state.
    #[must_use]
    pub const fn is_success(&self) -> bool {
        matches!(
            self,
            Self::Applied | Self::Noop | Self::PreviewPromoted | Self::AppliesAfterRestart
        )
    }

    /// Returns true when the attempted owner may require compensation.
    #[must_use]
    pub fn needs_compensation(&self) -> bool {
        matches!(
            self,
            Self::PartialFailure { .. }
                | Self::RendererRecreationFailed {
                    failure: SettingsApplyFailure::ApplyAndRollbackFailed { .. }
                }
        )
    }
}

/// Per-group route report for changed/skipped/failed/conflicted settings.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppRouteGroupReport {
    /// Owner-defined atomic group.
    pub group: AppRuntimeRouteGroup,

    /// Result for this group.
    pub result: AppRouteApplyResult,

    /// Concrete setting ids affected by this group.
    pub affected_settings: Vec<SettingId>,
}

/// Project-specific route report that preserves group-level details.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppRouteApplyReport {
    /// Typed owner route.
    pub route: AppRuntimeRoute,

    /// Concrete metadata routes that contributed to this owner route.
    pub source_routes: Vec<SettingRouteId>,

    /// Route-level result.
    pub result: AppRouteApplyResult,

    /// Runtime mechanism used by the owner.
    pub mechanism: ApplyMechanism,

    /// Concrete setting ids affected by this route.
    pub affected_settings: Vec<SettingId>,

    /// Owner-defined group details.
    pub groups: Vec<AppRouteGroupReport>,
}

impl AppRouteApplyReport {
    /// Converts to the neutral `settings-core` report expected by the controller.
    #[must_use]
    pub fn into_core_report(self) -> ApplyRouteReport {
        let route_id = self
            .source_routes
            .first()
            .cloned()
            .unwrap_or_else(|| route_id_for_runtime_route(self.route));
        let result = match self.result {
            // Для транзакции настроек значение «принято и сохраняется» равно успеху;
            // различие остаётся в project-level отчёте.
            AppRouteApplyResult::Applied | AppRouteApplyResult::AppliesAfterRestart => {
                ApplyRouteResult::Applied
            }
            AppRouteApplyResult::Noop => ApplyRouteResult::Noop,
            AppRouteApplyResult::PreviewPromoted => ApplyRouteResult::PreviewPromoted,
            AppRouteApplyResult::PartialFailure { message } => {
                ApplyRouteResult::PartialFailure { message }
            }
            AppRouteApplyResult::Failed { message } => ApplyRouteResult::Failed { message },
            AppRouteApplyResult::RendererRecreationFailed { failure } => ApplyRouteResult::Failed {
                message: renderer_recreation_failure_message(&failure),
            },
            AppRouteApplyResult::RuntimeBusy { activity } => ApplyRouteResult::RuntimeBusy {
                activity: format!("{activity:?}"),
            },
            AppRouteApplyResult::Conflict { baseline, current } => {
                ApplyRouteResult::Conflict { baseline, current }
            }
        };

        ApplyRouteReport {
            route: route_id,
            result,
            mechanism: self.mechanism,
            affected_settings: self.affected_settings,
        }
    }

    /// Converts an owner rollback attempt to the neutral transaction report.
    #[must_use]
    pub fn into_rollback_report(self) -> RollbackReport {
        let route = self
            .source_routes
            .first()
            .cloned()
            .unwrap_or_else(|| route_id_for_runtime_route(self.route));
        let result = match self.result {
            AppRouteApplyResult::Applied
            | AppRouteApplyResult::PreviewPromoted
            | AppRouteApplyResult::AppliesAfterRestart => RollbackResult::RolledBack,
            AppRouteApplyResult::Noop => RollbackResult::Noop,
            failure => RollbackResult::Failed {
                message: app_route_failure_message(&failure),
            },
        };
        RollbackReport {
            route,
            result,
            affected_settings: self.affected_settings,
        }
    }
}

fn app_route_failure_message(result: &AppRouteApplyResult) -> String {
    match result {
        AppRouteApplyResult::PartialFailure { message }
        | AppRouteApplyResult::Failed { message } => message.clone(),
        AppRouteApplyResult::RendererRecreationFailed { failure } => {
            renderer_recreation_failure_message(failure)
        }
        AppRouteApplyResult::RuntimeBusy { activity } => {
            format!("runtime boundary is busy ({activity:?}); update was not queued")
        }
        AppRouteApplyResult::Conflict { baseline, current } => format!(
            "runtime generation conflict: baseline {}, current {}",
            baseline.value(),
            current.value()
        ),
        AppRouteApplyResult::Applied
        | AppRouteApplyResult::Noop
        | AppRouteApplyResult::PreviewPromoted
        | AppRouteApplyResult::AppliesAfterRestart => {
            "rollback report requested for a successful route".to_string()
        }
    }
}

/// Формирует UI/core diagnostic, сохраняя typed failure в project route report-е.
fn renderer_recreation_failure_message(failure: &RendererRecreationFailure) -> String {
    match failure {
        SettingsApplyFailure::ApplyFailed { error, .. } => {
            format!("renderer recreation {:?}: {}", error.kind, error.message)
        }
        SettingsApplyFailure::ApplyAndRollbackFailed {
            apply_error,
            rollback_error,
            ..
        } => format!(
            "renderer recreation {:?}: {}; rollback {:?}: {}",
            apply_error.kind, apply_error.message, rollback_error.kind, rollback_error.message
        ),
    }
}

/// Builds renderer-neutral live settings from a validated app config snapshot.
pub fn render_live_settings_from_config(config: &AppConfig) -> SettingsResult<RenderLiveSettings> {
    Ok(RenderLiveSettings {
        color_pipeline: color_pipeline_settings_from_config(config)?,
        hdr_to_sdr: hdr_to_sdr_settings_from_config(config),
        shader_parameters: Default::default(),
    })
}

/// Builds a full typed route plan from a registry diff.
pub fn runtime_route_plan_from_diff(
    registry: &SettingsRegistry<AppConfig>,
    previous: &AppConfig,
    current: &AppConfig,
    diff: &SettingsDiff,
    automatic_surface_pool: AutomaticSurfacePool,
) -> SettingsResult<RuntimeRoutePlan> {
    let mut route_inputs: BTreeMap<AppRuntimeRoute, RouteInput> = BTreeMap::new();

    for change in diff.changes() {
        let descriptor =
            registry
                .descriptor(&change.id)
                .ok_or_else(|| SettingsError::UnknownSetting {
                    id: change.id.clone(),
                })?;
        let route = runtime_route_from_descriptor(descriptor)?;
        route_inputs
            .entry(route)
            .or_insert_with(|| RouteInput::new(route))
            .push_change(change, descriptor.route.clone());
    }

    let mut plan = RuntimeRoutePlan::default();
    for input in route_inputs.into_values() {
        match input.route {
            AppRuntimeRoute::RenderPreview => {
                plan.preview_routes
                    .push(render_preview_route(previous, current, input.clone())?);
                plan.committed_routes
                    .push(render_preview_committed_route(previous, current, input)?);
            }
            AppRuntimeRoute::Ui => plan
                .committed_routes
                .push(ui_committed_route(current, input)),
            AppRuntimeRoute::RenderCommitted => plan
                .committed_routes
                .push(render_committed_route(current, input)),
            AppRuntimeRoute::Player => plan.committed_routes.push(player_committed_route(
                current,
                input,
                automatic_surface_pool,
            )?),
            AppRuntimeRoute::MediaService => plan
                .committed_routes
                .push(media_service::committed_route(current, input)),
            AppRuntimeRoute::FrameServer => plan
                .committed_routes
                .push(frame_server_committed_route(current, input)),
            AppRuntimeRoute::Playlist => plan
                .committed_routes
                .push(playlist_committed_route(current, input)),
            AppRuntimeRoute::Subtitles => plan
                .committed_routes
                .push(subtitles::committed_route(current, input)),
        }
    }

    Ok(plan)
}

/// Builds committed routes from one controller route update.
///
/// Русский комментарий: `settings-derive` хранит route owner отдельно от
/// `apply_mode`, поэтому один metadata route вроде `render` может содержать и
/// preview, и committed settings. Здесь мы снова split-им его по setting id.
pub fn committed_routes_from_update(
    previous: &AppConfig,
    current: &AppConfig,
    update: &RouteApplyUpdate,
    automatic_surface_pool: AutomaticSurfacePool,
) -> SettingsResult<Vec<RuntimeCommittedRoute>> {
    let mut route_inputs: BTreeMap<AppRuntimeRoute, RouteInput> = BTreeMap::new();

    for setting_id in &update.affected_settings {
        let route = runtime_route_from_update_setting(&update.route, setting_id.as_str())?;
        route_inputs
            .entry(route)
            .or_insert_with(|| RouteInput::new(route))
            .push_setting_id(setting_id.clone(), update.route.clone());
    }

    let mut routes = Vec::new();
    for input in route_inputs.into_values() {
        let route = match input.route {
            AppRuntimeRoute::Ui => ui_committed_route(current, input),
            AppRuntimeRoute::RenderPreview => {
                render_preview_committed_route(previous, current, input)?
            }
            AppRuntimeRoute::RenderCommitted => render_committed_route(current, input),
            AppRuntimeRoute::Player => {
                player_committed_route(current, input, automatic_surface_pool)?
            }
            AppRuntimeRoute::MediaService => media_service::committed_route(current, input),
            AppRuntimeRoute::FrameServer => frame_server_committed_route(current, input),
            AppRuntimeRoute::Playlist => playlist_committed_route(current, input),
            AppRuntimeRoute::Subtitles => subtitles::committed_route(current, input),
        };
        routes.push(route);
    }

    Ok(routes)
}

/// Builds the deterministic flat owner route order used by apply and reverse rollback.
pub fn committed_routes_for_updates(
    previous: &AppConfig,
    current: &AppConfig,
    updates: &[RouteApplyUpdate],
    automatic_surface_pool: AutomaticSurfacePool,
) -> SettingsResult<Vec<RuntimeCommittedRoute>> {
    let mut routes = Vec::new();
    for update in updates {
        routes.extend(committed_routes_from_update(
            previous,
            current,
            update,
            automatic_surface_pool,
        )?);
    }
    // Один и тот же owner исполняется связно независимо от алфавитного metadata route id.
    // Reverse rollback строит тот же порядок и разворачивает только completed prefix.
    routes.sort_by_key(|route| route.route);
    Ok(routes)
}

fn hdr_to_sdr_settings_from_config(config: &AppConfig) -> HdrToSdrSettings {
    let hdr_to_sdr = &config.render.hdr_to_sdr;

    HdrToSdrSettings {
        enabled: hdr_to_sdr.enabled,
        operator: hdr_to_sdr_operator_from_config(hdr_to_sdr.operator),
        output_mode: HdrOutputMode::SdrBt709Only,
        sdr_reference_white_nits: hdr_to_sdr.sdr_reference_white_nits,
        hdr_reference_peak_nits: hdr_to_sdr.hdr_reference_peak_nits,
    }
}

const fn hdr_to_sdr_operator_from_config(
    operator: HdrToSdrOperatorConfig,
) -> HdrToneMappingOperator {
    match operator {
        HdrToSdrOperatorConfig::Bt2446C => HdrToneMappingOperator::Bt2446C,
    }
}

fn color_pipeline_settings_from_config(
    config: &AppConfig,
) -> SettingsResult<ColorPipelineSettings> {
    let color_adjustment = &config.render.color_adjustment;

    Ok(ColorPipelineSettings {
        adjustment: ColorAdjustment {
            brightness: color_adjustment.brightness,
            contrast: color_adjustment.contrast,
            saturation: color_adjustment.saturation,
            exposure: color_adjustment.exposure,
            rgb_gain: rgb_triplet_from_config(
                "render.color_adjustment.rgb_gain",
                &color_adjustment.rgb_gain,
            )?,
            rgb_offset: rgb_triplet_from_config(
                "render.color_adjustment.rgb_offset",
                &color_adjustment.rgb_offset,
            )?,
        },
        tone_mapping: render_core::ToneMappingMode::Off,
        swapchain_transfer: SwapchainTransferMode::PreserveCurrentUnorm,
    })
}

fn rgb_triplet_from_config(field: &'static str, values: &[f32]) -> SettingsResult<[f32; 3]> {
    if values.len() != 3 {
        return Err(SettingsError::access_failed(format!(
            "{field} must contain exactly 3 values; got {}",
            values.len()
        )));
    }

    for (channel_index, channel_value) in values.iter().copied().enumerate() {
        if !channel_value.is_finite() {
            return Err(SettingsError::access_failed(format!(
                "{field}[{channel_index}] must be finite; got {channel_value}"
            )));
        }
    }

    Ok([values[0], values[1], values[2]])
}

#[derive(Debug, Clone)]
struct RouteInput {
    route: AppRuntimeRoute,
    source_routes: Vec<SettingRouteId>,
    affected_settings: Vec<SettingId>,
}

impl RouteInput {
    fn new(route: AppRuntimeRoute) -> Self {
        Self {
            route,
            source_routes: Vec::new(),
            affected_settings: Vec::new(),
        }
    }

    fn push_change(&mut self, change: &SettingChange, source_route: SettingRouteId) {
        self.push_setting_id(change.id.clone(), source_route);
    }

    fn push_setting_id(&mut self, setting_id: SettingId, source_route: SettingRouteId) {
        push_unique_setting_route(&mut self.source_routes, source_route);
        push_unique_setting_id(&mut self.affected_settings, setting_id);
    }

    fn groups(&self) -> Vec<AppRuntimeRouteGroupUpdate> {
        groups_for_settings(self.route, &self.affected_settings)
    }
}

fn render_preview_route(
    previous: &AppConfig,
    current: &AppConfig,
    input: RouteInput,
) -> SettingsResult<RuntimePreviewRoute> {
    let previous_settings = render_live_settings_from_config(previous)?;
    let current_settings = render_live_settings_from_config(current)?;
    let update = RenderLiveSettingsUpdate::from_baseline(&previous_settings, current_settings);
    let groups = input.groups();

    Ok(RuntimePreviewRoute {
        route: AppRuntimeRoute::RenderPreview,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimePreviewUpdate::Render(RenderPreviewSettingsUpdate {
            live_settings: update,
        }),
    })
}

fn render_preview_committed_route(
    previous: &AppConfig,
    current: &AppConfig,
    input: RouteInput,
) -> SettingsResult<RuntimeCommittedRoute> {
    let previous_settings = render_live_settings_from_config(previous)?;
    let current_settings = render_live_settings_from_config(current)?;
    let update = RenderLiveSettingsUpdate::from_baseline(&previous_settings, current_settings);
    let groups = input.groups();

    Ok(RuntimeCommittedRoute {
        route: AppRuntimeRoute::RenderPreview,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimeCommittedUpdate::RenderPreview(RenderPreviewSettingsUpdate {
            live_settings: update,
        }),
    })
}

fn ui_committed_route(current: &AppConfig, input: RouteInput) -> RuntimeCommittedRoute {
    let groups = input.groups();

    RuntimeCommittedRoute {
        route: AppRuntimeRoute::Ui,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimeCommittedUpdate::Ui(UiRuntimeSettingsUpdate {
            ui: current.ui.clone(),
        }),
    }
}

fn player_committed_route(
    current: &AppConfig,
    input: RouteInput,
    automatic_surface_pool: AutomaticSurfacePool,
) -> SettingsResult<RuntimeCommittedRoute> {
    let groups = input.groups();
    let update =
        player_update_from_settings(current, &input.affected_settings, automatic_surface_pool);

    Ok(RuntimeCommittedRoute {
        route: AppRuntimeRoute::Player,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimeCommittedUpdate::Player(Box::new(update?)),
    })
}

fn frame_server_committed_route(current: &AppConfig, input: RouteInput) -> RuntimeCommittedRoute {
    let groups = input.groups();
    let player_core = frame_server_player_update_from_settings(current, &input.affected_settings);

    RuntimeCommittedRoute {
        route: AppRuntimeRoute::FrameServer,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimeCommittedUpdate::FrameServer(Box::new(FrameServerRuntimeSettingsUpdate {
            frame_server: current.frame_server.clone(),
            player_core,
        })),
    }
}

/// Builds an atomic playlist owner payload.
fn playlist_committed_route(current: &AppConfig, input: RouteInput) -> RuntimeCommittedRoute {
    let groups = input.groups();
    RuntimeCommittedRoute {
        route: AppRuntimeRoute::Playlist,
        source_routes: input.source_routes,
        affected_settings: input.affected_settings,
        groups,
        update: RuntimeCommittedUpdate::Playlist(PlaylistRuntimeSettingsUpdate {
            playlist: current.playlist,
        }),
    }
}

fn frame_server_player_update_from_settings(
    current: &AppConfig,
    affected_settings: &[SettingId],
) -> PlayerRuntimeSettingsUpdate {
    let affected_runtime_settings = affected_settings
        .iter()
        .filter_map(|setting_id| frame_server_runtime_setting_id(setting_id.as_str()));

    PlayerRuntimeSettingsUpdate::empty().with_frame_server_policy(
        PlayerWorkerConfig::frame_server_config_from_app_config(current),
        affected_runtime_settings,
    )
}

fn player_update_from_settings(
    current: &AppConfig,
    affected_settings: &[SettingId],
    automatic_surface_pool: AutomaticSurfacePool,
) -> SettingsResult<PlayerCommittedSettingsUpdate> {
    let mut player_core = PlayerRuntimeSettingsUpdate::empty();
    let mut tick_settings = Vec::new();
    let mut decoder_settings = Vec::new();
    let mut event_policy_settings = Vec::new();
    let mut media_pipeline_settings = Vec::new();
    let mut default_volume_changed = false;
    let mut audio_output_device_changed = false;
    let mut video_backend_changed = false;

    for setting_id in affected_settings {
        let setting_name = setting_id.as_str();
        if setting_name == "audio.output_device" {
            audio_output_device_changed = true;
            continue;
        }
        if setting_name == "video.preferred_backend" {
            video_backend_changed = true;
            continue;
        }
        // UX-11: у mute нет worker policy; текущий звук после Apply доставляет app-слой.
        if setting_name == "audio.muted" {
            continue;
        }
        if matches!(
            setting_name,
            "player.start_paused"
                | "player.resume_last_position"
                | "player.seek.paused_commit_behavior"
                | "player.seek.hotkey_small_step_secs"
                | "player.seek.hotkey_large_step_secs"
        ) {
            event_policy_settings.push(setting_id.clone());
            continue;
        }
        if matches!(
            setting_name,
            "player.preferred_video_codec_order" | "player.demux.max_consecutive_corrupted_packets"
        ) {
            media_pipeline_settings.push(setting_id.clone());
            continue;
        }

        match player_runtime_setting_id(setting_name) {
            Some(PlayerRuntimeSettingId::AudioDefaultVolume) => {
                default_volume_changed = true;
            }
            Some(runtime_id) if player_decoder_ready_queue_setting(setting_name) => {
                tick_settings.push(runtime_id);
                decoder_settings.push(runtime_id);
            }
            Some(runtime_id) if player_tick_setting(setting_name) => {
                tick_settings.push(runtime_id);
            }
            Some(runtime_id) if player_decoder_thread_setting(setting_name) => {
                decoder_settings.push(runtime_id);
            }
            Some(runtime_id) => {
                return Err(SettingsError::access_failed(format!(
                    "setting `{setting_name}` has no live owner mechanism for `{runtime_id:?}`"
                )));
            }
            None => {
                return Err(SettingsError::access_failed(format!(
                    "setting `{setting_name}` has no typed runtime route"
                )));
            }
        }
    }

    if !tick_settings.is_empty() {
        player_core = player_core.with_tick_config(PlayerTickConfig::from(current), tick_settings);
    }
    if default_volume_changed {
        player_core = player_core.with_default_volume(
            current.audio.volume as f32,
            [PlayerRuntimeSettingId::AudioDefaultVolume],
        );
    }
    if audio_output_device_changed {
        player_core =
            player_core.with_audio_output_recreate([PlayerRuntimeSettingId::AudioOutputDevice]);
    }
    if !decoder_settings.is_empty() {
        player_core = player_core.with_decoder_thread_config(
            PlayerWorkerConfig::decoder_thread_config_from_app_config(
                current,
                automatic_surface_pool,
            ),
            decoder_settings,
        );
    }
    if video_backend_changed {
        let preference = match current.video.preferred_backend {
            VideoBackendPreference::Auto => PlayerRuntimeVideoBackendPreference::Auto,
            VideoBackendPreference::Hardware => PlayerRuntimeVideoBackendPreference::Hardware,
            VideoBackendPreference::Software => PlayerRuntimeVideoBackendPreference::Software,
            VideoBackendPreference::Dynamic => PlayerRuntimeVideoBackendPreference::Dynamic,
        };
        player_core = player_core
            .with_video_backend(preference, [PlayerRuntimeSettingId::VideoPreferredBackend]);
    }

    let resume_last_position = event_policy_settings
        .iter()
        .any(|setting_id| setting_id.as_str() == "player.resume_last_position")
        .then_some(current.player.resume_last_position);
    Ok(PlayerCommittedSettingsUpdate {
        player_core,
        audio_output_device_id: audio_output_device_changed
            .then(|| current.audio.output_device.clone()),
        event_policy_settings,
        resume_last_position,
        media_pipeline: (!media_pipeline_settings.is_empty()).then(|| {
            PlayerMediaPipelineSettingsUpdate {
                demux: current.player.demux,
                preferred_video_codec_order: current.player.preferred_video_codec_order.clone(),
                affected_settings: media_pipeline_settings,
            }
        }),
    })
}

pub(crate) fn runtime_route_from_descriptor(
    descriptor: &SettingDescriptor,
) -> SettingsResult<AppRuntimeRoute> {
    let metadata_route = runtime_route_from_metadata(
        &descriptor.route,
        descriptor.id.as_str(),
        descriptor.apply_mode,
    )?;
    let contract = setting_application_contract(&descriptor.id).ok_or_else(|| {
        SettingsError::access_failed(format!(
            "editable setting '{}' does not have a checked live application contract",
            descriptor.id.as_str()
        ))
    })?;

    if contract.route != metadata_route {
        return Err(SettingsError::access_failed(format!(
            "setting `{}': metadata route {:?} diverges from application contract route {:?}",
            descriptor.id.as_str(),
            metadata_route,
            contract.route
        )));
    }

    Ok(metadata_route)
}

fn runtime_route_from_update_setting(
    route: &SettingRouteId,
    setting_id: &str,
) -> SettingsResult<AppRuntimeRoute> {
    let apply_mode = if render_preview_setting(setting_id) {
        SettingApplyMode::ImmediatePreview
    } else {
        SettingApplyMode::CommittedApply
    };

    runtime_route_from_metadata(route, setting_id, apply_mode)
}

fn runtime_route_from_metadata(
    route: &SettingRouteId,
    setting_id: &str,
    apply_mode: SettingApplyMode,
) -> SettingsResult<AppRuntimeRoute> {
    match (route.as_str(), apply_mode) {
        (UI_ROUTE_ID, _) => Ok(AppRuntimeRoute::Ui),
        (RENDER_PREVIEW_ROUTE_ID, SettingApplyMode::ImmediatePreview) => {
            Ok(AppRuntimeRoute::RenderPreview)
        }
        (RENDER_COMMITTED_ROUTE_ID, SettingApplyMode::CommittedApply) => {
            Ok(AppRuntimeRoute::RenderCommitted)
        }
        (PLAYER_ROUTE_ID | AUDIO_ROUTE_ID | VIDEO_ROUTE_ID, _) => Ok(AppRuntimeRoute::Player),
        (NETWORK_ROUTE_ID | WEB_MEDIA_ROUTE_ID | YT_DLP_ROUTE_ID, _) => {
            Ok(AppRuntimeRoute::MediaService)
        }
        (FRAME_SERVER_ROUTE_ID, SettingApplyMode::CommittedApply) => {
            Ok(AppRuntimeRoute::FrameServer)
        }
        (PLAYLIST_ROUTE_ID, SettingApplyMode::CommittedApply) => Ok(AppRuntimeRoute::Playlist),
        (SUBTITLES_ROUTE_ID, SettingApplyMode::CommittedApply) => Ok(AppRuntimeRoute::Subtitles),
        (other, _) => Err(SettingsError::access_failed(format!(
            "unknown AppConfig settings route `{other}` for setting `{setting_id}`"
        ))),
    }
}

fn route_id_for_runtime_route(route: AppRuntimeRoute) -> SettingRouteId {
    match route {
        AppRuntimeRoute::Ui => SettingRouteId::from(UI_ROUTE_ID),
        AppRuntimeRoute::RenderPreview => SettingRouteId::from(RENDER_PREVIEW_ROUTE_ID),
        AppRuntimeRoute::RenderCommitted => SettingRouteId::from(RENDER_COMMITTED_ROUTE_ID),
        AppRuntimeRoute::Player => SettingRouteId::from(PLAYER_ROUTE_ID),
        AppRuntimeRoute::MediaService => SettingRouteId::from(NETWORK_ROUTE_ID),
        AppRuntimeRoute::FrameServer => SettingRouteId::from(FRAME_SERVER_ROUTE_ID),
        AppRuntimeRoute::Playlist => SettingRouteId::from(PLAYLIST_ROUTE_ID),
        AppRuntimeRoute::Subtitles => SettingRouteId::from(SUBTITLES_ROUTE_ID),
    }
}

fn groups_for_settings(
    route: AppRuntimeRoute,
    affected_settings: &[SettingId],
) -> Vec<AppRuntimeRouteGroupUpdate> {
    let mut groups: BTreeMap<AppRuntimeRouteGroup, Vec<SettingId>> = BTreeMap::new();
    for setting_id in affected_settings {
        groups
            .entry(group_for_setting(route, setting_id.as_str()))
            .or_default()
            .push(setting_id.clone());
    }

    groups
        .into_iter()
        .map(|(group, affected_settings)| AppRuntimeRouteGroupUpdate {
            group,
            affected_settings,
        })
        .collect()
}

fn group_for_setting(route: AppRuntimeRoute, setting_id: &str) -> AppRuntimeRouteGroup {
    match route {
        AppRuntimeRoute::Ui if setting_id.starts_with("ui.settings.") => {
            AppRuntimeRouteGroup::UiSettingsRuntime
        }
        AppRuntimeRoute::Ui => AppRuntimeRouteGroup::UiShell,
        AppRuntimeRoute::RenderPreview if setting_id.starts_with("render.hdr_to_sdr.") => {
            AppRuntimeRouteGroup::RenderHdrToSdr
        }
        AppRuntimeRoute::RenderPreview => AppRuntimeRouteGroup::RenderColorAdjustment,
        AppRuntimeRoute::RenderCommitted if setting_id == "render.profile" => {
            AppRuntimeRouteGroup::RenderProfileRestart
        }
        AppRuntimeRoute::RenderCommitted => AppRuntimeRouteGroup::RenderBackendLifecycle,
        AppRuntimeRoute::Player if matches!(setting_id, "audio.volume" | "audio.muted") => {
            AppRuntimeRouteGroup::PlayerDefaultVolume
        }
        AppRuntimeRoute::Player if setting_id == "audio.output_device" => {
            AppRuntimeRouteGroup::PlayerAudioOutputDevice
        }
        AppRuntimeRoute::Player if player_tick_setting(setting_id) => {
            AppRuntimeRouteGroup::PlayerTickConfig
        }
        AppRuntimeRoute::Player if player_decoder_thread_setting(setting_id) => {
            AppRuntimeRouteGroup::PlayerDecoderThreadConfig
        }
        AppRuntimeRoute::Player if setting_id == "video.preferred_backend" => {
            AppRuntimeRouteGroup::PlayerVideoBackend
        }
        AppRuntimeRoute::Player => AppRuntimeRouteGroup::PlayerDeferredBoundary,
        AppRuntimeRoute::MediaService if setting_id.starts_with("yt_dlp.") => {
            AppRuntimeRouteGroup::MediaYtDlp
        }
        AppRuntimeRoute::MediaService if setting_id.starts_with("web_media.") => {
            AppRuntimeRouteGroup::MediaWebMedia
        }
        AppRuntimeRoute::MediaService => AppRuntimeRouteGroup::MediaNetwork,
        AppRuntimeRoute::FrameServer => AppRuntimeRouteGroup::FrameServerSettings,
        AppRuntimeRoute::Playlist => AppRuntimeRouteGroup::PlaylistPolicy,
        AppRuntimeRoute::Subtitles => AppRuntimeRouteGroup::SubtitlePolicy,
    }
}

fn player_tick_setting(setting_id: &str) -> bool {
    matches!(
        setting_id,
        "audio.buffer_target_ms"
            | "audio.startup_read_ahead_cap_ms"
            | "player.seek.commit_timeout_ms"
            | "player.seek.resume_audio_min_buffer_ms"
            | "player.seek.resume_audio_gate_timeout_ms"
            | "player.seek.resume_video_min_ready_frames"
            | "player.seek.fast_preroll_budget_ms"
            | "player.seek.fast_preroll_video_packet_burst"
            | "video.max_decode_ahead_ms"
            | "video.present_queue_frames"
            | "video.scheduler.demux_packets_per_tick"
            | "video.scheduler.video_packets_per_tick"
            | "video.scheduler.decoded_frames_per_tick"
            | "video.scheduler.catch_up_budget_ms"
            | "video.scheduler.present_queue_min_frames"
            | "video.scheduler.present_queue_target_frames"
            | "video.scheduler.decode_ahead_target_ms"
            | "video.scheduler.surface_free_slots_min"
            | "video.scheduler.surface_free_slots_target"
    )
}

fn player_decoder_ready_queue_setting(setting_id: &str) -> bool {
    setting_id == "video.decoder_ready_queue_frames"
}

fn player_decoder_thread_setting(setting_id: &str) -> bool {
    matches!(
        setting_id,
        "video.decoder_packet_channel_frames"
            | "video.decoder_frame_channel_frames"
            | "video.decoder_ready_queue_frames"
            | "video.decoder_surface_pool_frames"
            | "video.sw_decoder_surface_pool_frames"
            | "video.sw_decode_threads"
            | "video.zero_copy_surface_pool_slots"
    )
}

fn render_preview_setting(setting_id: &str) -> bool {
    setting_id.starts_with("render.color_adjustment.")
        || setting_id.starts_with("render.hdr_to_sdr.")
}

fn player_runtime_setting_id(setting_id: &str) -> Option<PlayerRuntimeSettingId> {
    let runtime_id = match setting_id {
        "audio.volume" => PlayerRuntimeSettingId::AudioDefaultVolume,
        "audio.buffer_target_ms" => PlayerRuntimeSettingId::AudioBufferTargetMs,
        "audio.startup_read_ahead_cap_ms" => PlayerRuntimeSettingId::AudioStartupReadAheadCapMs,
        "player.demux.max_consecutive_corrupted_packets" => {
            PlayerRuntimeSettingId::PlayerDemuxMaxConsecutiveCorruptedPackets
        }
        "player.preferred_video_codec_order" => {
            PlayerRuntimeSettingId::PlayerPreferredVideoCodecOrder
        }
        "player.seek.commit_timeout_ms" => PlayerRuntimeSettingId::PlayerSeekCommitTimeoutMs,
        "player.seek.resume_audio_min_buffer_ms" => {
            PlayerRuntimeSettingId::PlayerSeekResumeAudioMinBufferMs
        }
        "player.seek.resume_audio_gate_timeout_ms" => {
            PlayerRuntimeSettingId::PlayerSeekResumeAudioGateTimeoutMs
        }
        "player.seek.resume_video_min_ready_frames" => {
            PlayerRuntimeSettingId::PlayerSeekResumeVideoMinReadyFrames
        }
        "player.seek.fast_preroll_budget_ms" => {
            PlayerRuntimeSettingId::PlayerSeekFastPrerollBudgetMs
        }
        "player.seek.fast_preroll_video_packet_burst" => {
            PlayerRuntimeSettingId::PlayerSeekFastPrerollVideoPacketBurst
        }
        "video.max_decode_ahead_ms" => PlayerRuntimeSettingId::VideoMaxDecodeAheadMs,
        "video.present_queue_frames" => PlayerRuntimeSettingId::VideoPresentQueueFrames,
        "video.decoder_packet_channel_frames" => {
            PlayerRuntimeSettingId::VideoDecoderPacketChannelFrames
        }
        "video.decoder_frame_channel_frames" => {
            PlayerRuntimeSettingId::VideoDecoderFrameChannelFrames
        }
        "video.decoder_ready_queue_frames" => PlayerRuntimeSettingId::VideoDecoderReadyQueueFrames,
        "video.decoder_surface_pool_frames" => {
            PlayerRuntimeSettingId::VideoDecoderSurfacePoolFrames
        }
        "video.sw_decoder_surface_pool_frames" => {
            PlayerRuntimeSettingId::VideoSoftwareDecoderSurfacePoolFrames
        }
        "video.sw_decode_threads" => PlayerRuntimeSettingId::VideoSoftwareDecodeThreads,
        "video.zero_copy_surface_pool_slots" => {
            PlayerRuntimeSettingId::VideoZeroCopySurfacePoolSlots
        }
        "video.scheduler.demux_packets_per_tick" => {
            PlayerRuntimeSettingId::VideoSchedulerDemuxPacketsPerTick
        }
        "video.scheduler.video_packets_per_tick" => {
            PlayerRuntimeSettingId::VideoSchedulerVideoPacketsPerTick
        }
        "video.scheduler.decoded_frames_per_tick" => {
            PlayerRuntimeSettingId::VideoSchedulerDecodedFramesPerTick
        }
        "video.scheduler.catch_up_budget_ms" => {
            PlayerRuntimeSettingId::VideoSchedulerCatchUpBudgetMs
        }
        "video.scheduler.present_queue_min_frames" => {
            PlayerRuntimeSettingId::VideoSchedulerPresentQueueMinFrames
        }
        "video.scheduler.present_queue_target_frames" => {
            PlayerRuntimeSettingId::VideoSchedulerPresentQueueTargetFrames
        }
        "video.scheduler.decode_ahead_target_ms" => {
            PlayerRuntimeSettingId::VideoSchedulerDecodeAheadTargetMs
        }
        "video.scheduler.surface_free_slots_min" => {
            PlayerRuntimeSettingId::VideoSchedulerSurfaceFreeSlotsMin
        }
        "video.scheduler.surface_free_slots_target" => {
            PlayerRuntimeSettingId::VideoSchedulerSurfaceFreeSlotsTarget
        }
        _ => return None,
    };

    Some(runtime_id)
}

fn frame_server_runtime_setting_id(setting_id: &str) -> Option<PlayerRuntimeSettingId> {
    let runtime_id = match setting_id {
        "frame_server.live_scrub_enabled" => PlayerRuntimeSettingId::FrameServerLiveScrubEnabled,
        "frame_server.live_scrub_decode_mode" => {
            PlayerRuntimeSettingId::FrameServerLiveScrubDecodeMode
        }
        "frame_server.live_scrub_max_hz" => PlayerRuntimeSettingId::FrameServerLiveScrubMaxHz,
        _ => return None,
    };

    Some(runtime_id)
}

pub(crate) fn setting_ids_from_diff(diff: &SettingsDiff) -> Vec<SettingId> {
    diff.changes()
        .iter()
        .map(|change| change.id.clone())
        .collect()
}

fn push_unique_setting_id(ids: &mut Vec<SettingId>, id: SettingId) {
    if !ids.iter().any(|existing| existing == &id) {
        ids.push(id);
    }
}

fn push_unique_setting_route(routes: &mut Vec<SettingRouteId>, route: SettingRouteId) {
    if !routes.iter().any(|existing| existing == &route) {
        routes.push(route);
    }
}

pub(crate) fn settings_error_from_display(error: impl std::fmt::Display) -> SettingsError {
    SettingsError::access_failed(error.to_string())
}

